// Zwraca PIERWSZA wartosc parametru o danej nazwie (String),
// albo null, jesli parametr nie wystepuje w zadaniu.

String bodyProste = "imie=Jan&wiek=25";
HttpRequest requestProsty = HttpRequest.newBuilder(URI.create(url))
        .header("Content-Type", "application/x-www-form-urlencoded")
        .POST(HttpRequest.BodyPublishers.ofString(bodyProste))
        .build();

// serwer: String imie = req.getParameter("imie"); // "Jan"
// String wiek = req.getParameter("wiek"); // "25"

// Checkboxy (i multi-select) moga wyslac TE SAMA nazwe parametru
// wielokrotnie - np. kolor=niebieski&kolor=zielony.
// getParameter("kolor") zwrocilby wtedy TYLKO pierwsza wartosc
// ("niebieski") - reszta by "zniknela". Zeby dostac WSZYSTKIE
// wartosci, trzeba uzyc getParameterValues(name), ktore zwraca
// String[] (albo null, jesli parametr nie istnieje).

String bodyMulti = "imie=Ania&kolor=niebieski&kolor=zielony&kolor=czerwony";

// serwer: String[] kolory = req.getParameterValues("kolor");
// -> ["niebieski", "zielony", "czerwony"]
// req.getParameter("kolor") dalby TYLKO "niebieski"

Map<String, String[]> paramMap = req.getParameterMap();
for (Map.Entry<String, String[]> entry : paramMap.entrySet()) {
    sb.append(entry.getKey()).append(" = ")
            .append(String.join(", ", entry.getValue())).append("\n");
}
